"use client";

import { useMemo, useState, type FormEvent } from "react";
import type { ConfigurationInventory } from "@/lib/d5o/configuration/version-inventory";
import { verifyActiveConfigurationPin } from "@/app/work/configuration-actions";
import { activePhaseConfigurationVersion, phaseContractFromManifest } from "./published-phase-configuration";
import { assessDiscover, assessmentBasis, activeForecast, resolveDiscoverPolicy, weightedPotential } from "./discover-decision";
import { groupIndicativeOrders, type ForecastPeriod } from "./discover-forecast";
import { blankPursuit, type PursuitCommand } from "./pursuit-control";
import { PursuitControl } from "./PursuitControl";
import { FocusedTaskFrame } from "./FocusedTaskFrame";
import type { DiscoverCRM, DiscoveryRecord, WorkRecord, WorkspaceKey } from "./work-types";
import { WorkPhaseJourney, type WorkControl, type WorkPhase } from "./WorkPhaseJourney";
import styles from "./DiscoverCRMWorkspace.module.css";

type View = "All opportunities" | "My opportunities" | "Under assessment" | "Awaiting customer" | "Awaiting decision" | "Recommended" | "Conditional" | "Held" | "Declined" | "Expected awards" | "Expected awards this quarter" | "Overdue" | "Awaiting Define";
type Tab = "Overview" | "People & buying" | "Activity & tasks" | "Qualification" | "Evidence" | "Forecast" | "Decision & handoff";
type SavedView = { name: string; view: View; search: string; ownerFilter: string; serviceFilter: string; customerFilter: string; commercialFilter: string; riskFilter: string; sort: "Next action" | "Award date" | "Value"; display: "Table" | "Board" };
const views: View[] = ["All opportunities", "My opportunities", "Under assessment", "Awaiting customer", "Awaiting decision", "Recommended", "Conditional", "Held", "Declined", "Expected awards", "Expected awards this quarter", "Overdue", "Awaiting Define"];
const tabs: Tab[] = ["Overview", "People & buying", "Activity & tasks", "Qualification", "Evidence", "Forecast", "Decision & handoff"];
const today = () => new Date().toISOString().slice(0, 10);
const field = (form: FormData, key: string) => String(form.get(key) ?? "").trim();
const money = (value: number, currency: string) => /^[A-Z]{3}$/.test(currency)
  ? new Intl.NumberFormat("en-US", { style: "currency", currency, maximumFractionDigits: 0 }).format(value)
  : `${currency || "Currency unknown"} ${new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 }).format(value)}`;
const blankCRM = (): DiscoverCRM => ({ customerResolved: false, siteResolved: false, contacts: [], activities: [], tasks: [], buyingProcess: "", funding: "Unknown", commercialStatus: "Unknown", competition: "", access: "", strategicFit: null, needCredibility: null, commercialAttractiveness: null, deliveryFeasibility: null, risk: null, disqualifier: "None", forecast: { value: null, currency: "USD", basis: "", probability: null, awardDate: "", category: "Unspecified", rationale: "" }, assessmentHistory: [] });
const blankDiscovery = (): DiscoveryRecord => ({ source: "Direct customer", need: "", procurement: "Direct award", phase: "Qualification", fit: "Unassessed", closeDate: "", pursuitControl: blankPursuit(), crm: blankCRM(), estimate: { revision: 0, labor: 0, materials: 0, subcontract: 0, travel: 0, contingency: 0, targetMargin: 25, sellPrice: 0, status: "Not started", assumption: "" }, proposal: { status: "Not started", dueDate: "", method: "Customer portal", recipient: "", response: "" } });
const num = (value: string) => value === "" ? null : Number(value);

export function DiscoverCRMWorkspace({ workspaceKey, workspaceName, configurationInventory, work, actor, actorId, actorRole, canEdit, focusRecordId, taskFocus, onOpen, onDefine, onPhase, onControl, onBack, onSelect, onPursuitCommand, onUpdate, onCreate, onNotice }: {
  workspaceKey: WorkspaceKey; workspaceName: string; configurationInventory: ConfigurationInventory; work: WorkRecord[]; actor: string; actorId?: string; actorRole?: string; canEdit: boolean; focusRecordId?: string; taskFocus?: "pursuit-prep" | "pursuit-review" | "define-handoff-prep" | "define-handoff-receive" | null;
  onOpen: (record: WorkRecord) => void; onDefine: (record: WorkRecord) => void; onPhase: (record: WorkRecord, phase: WorkPhase) => void; onControl: (record: WorkRecord, control: WorkControl) => void; onBack: () => void; onSelect: (id: string) => void;
  onPursuitCommand?: (workId: string, command: PursuitCommand) => Promise<boolean>;
  onUpdate: (id: string, transform: (current: WorkRecord) => WorkRecord) => void; onCreate: (record: WorkRecord) => Promise<string> | string; onNotice: (message: string) => void;
}) {
  const [view, setView] = useState<View>("All opportunities");
  const [surface, setSurface] = useState<"Pipeline" | "Forecast">("Pipeline");
  const [tab, setTab] = useState<Tab>("Overview");
  const [display, setDisplay] = useState<"Table" | "Board">("Table");
  const [search, setSearch] = useState("");
  const [sort, setSort] = useState<"Next action" | "Award date" | "Value">("Next action");
  const [ownerFilter, setOwnerFilter] = useState("");
  const [serviceFilter, setServiceFilter] = useState("");
  const [customerFilter, setCustomerFilter] = useState("");
  const [commercialFilter, setCommercialFilter] = useState("");
  const [riskFilter, setRiskFilter] = useState("");
  const [forecastPeriod, setForecastPeriod] = useState<ForecastPeriod>("month");
  const [forecastFocus, setForecastFocus] = useState<string[]>([]);
  const [savedViews, setSavedViews] = useState<SavedView[]>([]);
  const [savingView, setSavingView] = useState(false);
  const [viewName, setViewName] = useState("");
  const [taskDraft, setTaskDraft] = useState("");
  const [captureOpen, setCaptureOpen] = useState(false);
  const [customerOpen, setCustomerOpen] = useState(false);
  const [saving, setSaving] = useState(false);
  const opportunities = useMemo(() => work.filter((item) => item.workspace === workspaceKey && item.discovery), [work, workspaceKey]);
  const configuredTypes = phaseContractFromManifest(
    configurationInventory.versions.find((item) => item.id === configurationInventory.activeVersionId)?.config_manifest_json,
    workspaceKey)?.workTypes.map((item) => item.workTypeLabel) ?? [];
  const selected = opportunities.find((item) => item.id === focusRecordId) ?? (taskFocus ? undefined : opportunities[0]);
  const crmEditable = canEdit && (!selected || selected.discovery?.phase === "Qualification" && !selected.definition);
  const crm = selected?.discovery?.crm ?? blankCRM();
  const assessment = crm.assessmentHistory.at(-1);
  const versionId = selected?.phaseConfigurationVersionId ?? "";
  const version = configurationInventory.versions.find((item) => item.id === versionId);
  const policy = resolveDiscoverPolicy(version?.config_manifest_json, versionId);
  const changesSinceAssessment = Boolean(assessment && selected && assessment.basis !== assessmentBasis(selected));
  const accountRecords = selected ? opportunities.filter((item) => item.customer.trim().toLowerCase() === selected.customer.trim().toLowerCase()) : [];
  const accountContacts = [...new Map(accountRecords.flatMap((item) => item.discovery?.crm?.contacts ?? []).map((person) => [person.id, person])).values()];
  const reusableContacts = [...new Map(opportunities.flatMap((item) => item.discovery?.crm?.contacts ?? []).map((person) => [person.id, person])).values()];
  const visible = useMemo(() => opportunities.filter((item) => {
    const d = item.discovery!; const c = d.crm; const a = c?.assessmentHistory.at(-1); const state = d.pursuitControl?.status;
    const due = item.nextActionDue ?? "";
    const matchView = view === "All opportunities" || view === "My opportunities" && item.owner.toLowerCase() === actor.toLowerCase()
      || view === "Under assessment" && (state === "draft" || state === "returned") || view === "Awaiting customer" && Boolean(c?.tasks.some((task) => task.status === "Open" && task.owner.toLowerCase().includes("customer")))
      || view === "Awaiting decision" && state === "submitted" || view === "Recommended" && a?.recommendation === "Pursue" && a.basis === assessmentBasis(item)
      || view === "Conditional" && a?.recommendation === "Pursue with conditions" && a.basis === assessmentBasis(item) || view === "Held" && state === "held" || view === "Declined" && state === "declined"
      || view === "Expected awards" && activeForecast(item) && Boolean(c?.forecast.awardDate && c.forecast.awardDate.slice(0, 7) === today().slice(0, 7))
      || view === "Expected awards this quarter" && activeForecast(item) && Boolean(c?.forecast.awardDate && c.forecast.awardDate.slice(0, 4) === today().slice(0, 4) && Math.ceil(Number(c.forecast.awardDate.slice(5, 7)) / 3) === Math.ceil(Number(today().slice(5, 7)) / 3))
      || view === "Overdue" && Boolean(due && due < today() || c?.tasks.some((task) => task.status === "Open" && task.due < today()))
      || view === "Awaiting Define" && state === "qualified" && d.pursuitControl?.handoff?.status !== "accepted";
    return matchView && (!search || `${item.title} ${item.customer} ${item.site} ${item.type}`.toLowerCase().includes(search.toLowerCase()))
      && (!ownerFilter || item.owner === ownerFilter) && (!serviceFilter || item.type === serviceFilter)
      && (!customerFilter || item.customer === customerFilter) && (!commercialFilter || c?.commercialStatus === commercialFilter)
      && (!riskFilter || (riskFilter === "Restricted" ? c?.disqualifier !== "None" && Boolean(c?.disqualifier) : (a?.coverage ?? 0) < 100));
  }).sort((a, b) => sort === "Value" ? (b.discovery?.crm?.forecast.value ?? 0) - (a.discovery?.crm?.forecast.value ?? 0) : sort === "Award date" ? (a.discovery?.crm?.forecast.awardDate || "9999").localeCompare(b.discovery?.crm?.forecast.awardDate || "9999") : (a.nextActionDue || "9999").localeCompare(b.nextActionDue || "9999")), [opportunities, view, actor, search, ownerFilter, serviceFilter, customerFilter, commercialFilter, riskFilter, sort]);
  const forecastRows = opportunities.filter(activeForecast).map((item) => ({ item, forecast: item.discovery?.crm?.forecast })).filter((row) => row.forecast);
  const forecastGroups = groupIndicativeOrders(opportunities, forecastPeriod, today());
  const timeline = selected ? [
    ...crm.activities.map((activity) => ({ at: activity.at, title: activity.kind, detail: activity.summary, actor: activity.author })),
    ...crm.assessmentHistory.map((entry) => ({ at: entry.at, title: `Assessment revision ${entry.revision}: ${entry.recommendation}`, detail: `Policy ${entry.policyVersion} · ${entry.coverage}% coverage`, actor: selected.owner })),
    ...(selected.discovery?.pursuitControl?.history ?? []).map((entry) => ({ at: entry.at, title: entry.action, detail: entry.note, actor: entry.actor })),
  ].sort((a, b) => b.at.localeCompare(a.at)) : [];
  function loadSavedViews() { try { const raw = localStorage.getItem(`d5o-discover-views:${workspaceKey}`); const parsed: unknown = raw ? JSON.parse(raw) : []; setSavedViews(Array.isArray(parsed) ? parsed as SavedView[] : []); } catch { setSavedViews([]); } }
  function saveCurrentView() { if (!viewName.trim()) return; const item: SavedView = { name: viewName.trim().slice(0, 50), view, search, ownerFilter, serviceFilter, customerFilter, commercialFilter, riskFilter, sort, display }; const next = [...savedViews.filter((saved) => saved.name !== item.name), item]; setSavedViews(next); localStorage.setItem(`d5o-discover-views:${workspaceKey}`, JSON.stringify(next)); setSavingView(false); setViewName(""); onNotice(`Pipeline view “${item.name}” saved in this browser.`); }
  function applySavedView(name: string) { const item = savedViews.find((saved) => saved.name === name); if (!item) return; setView(item.view); setSearch(item.search); setOwnerFilter(item.ownerFilter); setServiceFilter(item.serviceFilter); setCustomerFilter(item.customerFilter); setCommercialFilter(item.commercialFilter ?? ""); setRiskFilter(item.riskFilter); setSort(item.sort); setDisplay(item.display); }
  function update(transform: (crm: DiscoverCRM) => DiscoverCRM, note: string) {
    if (!selected || !crmEditable) return;
    onUpdate(selected.id, (current) => current.discovery ? { ...current, discovery: { ...current.discovery, crm: transform(current.discovery.crm ?? blankCRM()) }, history: [`${new Date().toISOString()} · ${note} by ${actor}`, ...current.history] } : current);
    onNotice(`${note} prepared; saving to the shared prototype workspace.`);
  }
  async function capture(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); if (!canEdit || saving) return;
    const form = new FormData(event.currentTarget); const type = field(form, "type");
    const pin = activePhaseConfigurationVersion(configurationInventory, workspaceKey, type);
    if (!pin) { onNotice("A published Work Type configuration is required before capture."); return; }
    setSaving(true);
    try {
      const checked = await verifyActiveConfigurationPin(configurationInventory.workspaceId, pin);
      if (!checked.ok) { onNotice("The published configuration changed. Refresh before capture."); return; }
      const id = `${workspaceKey}-discover-${crypto.randomUUID()}`; const discovery = blankDiscovery(); discovery.source = field(form, "source"); discovery.need = field(form, "need");
      const record: WorkRecord = { id, workspace: workspaceKey, title: field(form, "title"), customer: field(form, "customer"), site: field(form, "site") || "To be confirmed", type, phaseConfigurationVersionId: pin,
        stage: "Intake & Shape", owner: field(form, "owner") || "Unassigned", nextAction: "Qualify customer need", nextActionDue: null, nextActionImpact: "High", progress: 5, value: "Unpriced", status: "moving", proof: [], blockers: [], history: [`${new Date().toISOString()} · Opportunity captured by ${actor}`], discovery };
      const createdId = await onCreate(record);
      onSelect(createdId); setCaptureOpen(false); setTab("Overview");
      onNotice("Opportunity captured on its canonical Work Record.");
    } catch (error) {
      onNotice(error instanceof Error ? error.message : "The opportunity could not be created. Your form remains open.");
    } finally { setSaving(false); }
  }
  function saveOverview(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const f = new FormData(event.currentTarget); if (!selected || !crmEditable) return;
    onUpdate(selected.id, (current) => current.discovery ? { ...current, owner: field(f, "owner"), site: field(f, "site"), nextAction: current.canonicalWorkId ? current.nextAction : field(f, "nextAction"), nextActionDue: field(f, "nextDue") || null, discovery: { ...current.discovery, need: field(f, "need"), source: field(f, "source"), procurement: field(f, "procurement"), crm: { ...(current.discovery.crm ?? blankCRM()), buyingProcess: field(f, "buyingProcess"), desiredOutcome: field(f, "desiredOutcome"), businessImpact: field(f, "businessImpact"), urgency: field(f, "urgency") as DiscoverCRM["urgency"], preliminaryScope: field(f, "preliminaryScope"), geography: field(f, "geography"), customerRelationship: field(f, "customerRelationship"), competition: field(f, "competition"), access: field(f, "access"), funding: field(f, "funding") as DiscoverCRM["funding"], commercialStatus: field(f, "commercialStatus") as DiscoverCRM["commercialStatus"], externalCrmRef: field(f, "externalCrmRef") } }, history: [`${new Date().toISOString()} · Discover working details updated by ${actor}`, ...current.history] } : current);
    onNotice("Discover working details prepared; shared save is pending.");
  }
  function addContact(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const f = new FormData(event.currentTarget); update((c) => ({ ...c, contacts: [...c.contacts, { id: crypto.randomUUID(), name: field(f, "name"), organization: field(f, "organization"), role: field(f, "role") as DiscoverCRM["contacts"][number]["role"], influence: field(f, "influence") as DiscoverCRM["contacts"][number]["influence"], relationship: "Introduced", note: field(f, "note") }] }), "Stakeholder added"); event.currentTarget.reset(); }
  function linkContact(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const f = new FormData(event.currentTarget); const existing = reusableContacts.find((person) => person.id === field(f, "contactId")); if (!existing || crm.contacts.some((person) => person.id === existing.id)) return;
    update((c) => ({ ...c, contacts: [...c.contacts, { ...existing, role: field(f, "role") as DiscoverCRM["contacts"][number]["role"], note: field(f, "note") }] }), "Existing contact linked to opportunity"); event.currentTarget.reset(); }
  function addActivity(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const f = new FormData(event.currentTarget); const action = field(f, "resultingAction"); const taskId = action ? crypto.randomUUID() : undefined; const now = new Date().toISOString();
    if (action && !field(f, "actionDue")) { onNotice("Set a due date for the resulting action."); return; }
    update((c) => ({ ...c, activities: [...c.activities, { id: crypto.randomUUID(), at: now, author: actor, kind: field(f, "kind") as DiscoverCRM["activities"][number]["kind"], contacts: f.getAll("contacts").map(String), summary: field(f, "summary"), resultingAction: action || undefined, taskId }], tasks: taskId ? [...c.tasks, { id: taskId, title: action, owner: field(f, "actionOwner") || actor, due: field(f, "actionDue"), status: "Open", createdAt: now }] : c.tasks }), "Customer activity recorded"); event.currentTarget.reset(); }
  function addTask(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const f = new FormData(event.currentTarget); update((c) => ({ ...c, tasks: [...c.tasks, { id: crypto.randomUUID(), title: field(f, "title"), owner: field(f, "owner"), due: field(f, "due"), status: "Open", createdAt: new Date().toISOString() }] }), "Follow-up task created"); setTaskDraft(""); event.currentTarget.reset(); }
  function saveAssessment(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const f = new FormData(event.currentTarget); if (!selected || !crmEditable) return;
    const next = { ...crm, strategicFit: num(field(f, "strategicFit")), needCredibility: num(field(f, "needCredibility")), commercialAttractiveness: num(field(f, "commercialAttractiveness")), deliveryFeasibility: num(field(f, "deliveryFeasibility")), risk: num(field(f, "risk")), disqualifier: field(f, "disqualifier") as DiscoverCRM["disqualifier"] };
    const assessed = assessDiscover({ ...selected, discovery: { ...selected.discovery!, crm: next } }, policy);
    update(() => ({ ...next, assessmentHistory: [...crm.assessmentHistory, assessed] }), `Assessment revision ${assessed.revision} recorded`);
  }
  function saveForecast(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const f = new FormData(event.currentTarget); const at = new Date().toISOString();
    update((c) => { const forecast = { value: num(field(f, "value")), currency: field(f, "currency").toUpperCase(), basis: field(f, "basis"), probability: num(field(f, "probability")), awardDate: field(f, "awardDate"), category: field(f, "category") as DiscoverCRM["forecast"]["category"], rationale: field(f, "rationale"), reviewedAt: at };
      const weighted = weightedPotential({ ...c, forecast }); return { ...c, forecast, forecastSnapshots: [...(c.forecastSnapshots ?? []), { at, period: forecast.awardDate.slice(0, 7), currency: forecast.currency, workRevision: selected?.discovery?.pursuitControl?.revision ?? 0, value: forecast.value, probability: forecast.probability, weighted, category: forecast.category, awardDate: forecast.awardDate, workId: selected?.id }] }; }, "Indicative forecast snapshot recorded");
  }
  if (taskFocus && !selected) return <main className="d5o-page"><section role="alert"><h2>This task is unavailable</h2><p>The exact Discover record is no longer available. No other opportunity was selected.</p><button type="button" onClick={onBack}>Back to tasks</button></section></main>;
  if (taskFocus && selected && selected.id === focusRecordId) {
    const pursuit = selected.discovery?.pursuitControl;
    const receive = taskFocus === "define-handoff-receive";
    return <main className="d5o-page d5o-early-phase"><FocusedTaskFrame
      title={taskFocus === "pursuit-review" ? "Review Discover intake" : receive ? "Receive Define handoff" : taskFocus === "define-handoff-prep" ? "Prepare Define handoff" : "Prepare Discover intake"}
      work={selected.title} customer={selected.customer} site={selected.site} workspace={workspaceKey}
      scope={receive ? `Exact brief for ${pursuit?.handoff?.receiver}: ${pursuit?.handoff?.brief || "Unavailable"}` : selected.discovery?.need || "Customer need not recorded"}
      revision={pursuit?.revision ?? 0}
      outcome={taskFocus === "pursuit-review" ? "Decide the exact submitted intake independently, with a retained reason." : receive ? "Accept this exact qualified pursuit brief into Define, or return it with corrections." : taskFocus === "define-handoff-prep" ? "Name an independent receiver and submit the qualified pursuit brief." : "Save the customer need and submit the current intake for an independent pursuit decision."}
      nextOwner={taskFocus === "pursuit-review" ? "Project manager to prepare Define handoff or correct the intake" : receive ? "Project manager to prepare Define" : taskFocus === "define-handoff-prep" ? "Named Define receiver" : "Pursuit decision authority"}
      onFullRecord={() => onOpen(selected)} context={<p>Customer need: {selected.discovery?.need || "Not recorded"}. Risk: {pursuit?.knownRisk || "Not recorded"}.</p>}>
      <PursuitControl work={selected} actor={actor} canEdit={canEdit || (taskFocus === "pursuit-review" && Boolean(actorId && pursuit?.submission?.actorId !== actorId) && ["admin", "billing_commercial_lead", "business_development_lead"].includes(actorRole ?? ""))}
        connected={Boolean(selected.canonicalWorkId && onPursuitCommand)} taskMode={taskFocus === "pursuit-review" ? "intake-review" : receive ? "handoff-receive" : taskFocus === "define-handoff-prep" ? "handoff-prep" : "intake"}
        onCommand={onPursuitCommand} onUpdate={onUpdate} onNotice={onNotice} onDefine={onDefine} />
    </FocusedTaskFrame></main>;
  }
  return <main className={`d5o-page d5o-record-full d5o-early-phase ${styles.page}`}>
    <WorkPhaseJourney active="Discover" record={selected} backLabel="Work hub" onBack={onBack} onChoose={(phase) => { if (selected) onPhase(selected, phase); }} onControl={(control) => { if (selected) onControl(selected, control); }} />
    <header className={`${styles.hero} d5o-page-band`}><div><p className={styles.eyebrow}>D1 DISCOVER · {workspaceName.toUpperCase()}</p><h1>Customers and opportunities</h1><p>Develop the relationship, qualify the need, and decide what to pursue. Decisions and spend remain separate.</p></div><button className="d5o-primary" disabled={!canEdit} onClick={() => setCaptureOpen(true)}>+ Capture opportunity</button></header>
    <nav className={`${styles.surfaceNav} d5o-page-band`} aria-label="Discover views"><button type="button" className={surface === "Pipeline" ? styles.active : ""} aria-current={surface === "Pipeline" ? "page" : undefined} onClick={() => setSurface("Pipeline")}>Opportunity pipeline</button><button type="button" className={surface === "Forecast" ? styles.active : ""} aria-current={surface === "Forecast" ? "page" : undefined} onClick={() => setSurface("Forecast")}>Indicative order forecast</button></nav>
    {surface === "Pipeline" ? <>
    <div className={`${styles.summary} d5o-page-band`}><button onClick={() => setView("All opportunities")}><b>{opportunities.length}</b><span>Opportunities</span></button><button onClick={() => setView("Awaiting decision")}><b>{opportunities.filter((item) => item.discovery?.pursuitControl?.status === "submitted").length}</b><span>Awaiting decision</span></button><button onClick={() => setView("Overdue")}><b>{opportunities.filter((item) => item.nextActionDue && item.nextActionDue < today()).length}</b><span>Overdue follow-up</span></button><button onClick={() => { setSurface("Forecast"); setForecastFocus([]); }}><b>{forecastRows.length}</b><span>Open opportunities in outlook</span></button></div>
    <section className={`${styles.pipeline} d5o-page-band`}><div className={styles.pipelineHeader}><div><p className={styles.eyebrow}>DISCOVER · ALL OPPORTUNITIES</p><h2>Opportunity pipeline</h2></div><div className={styles.segment}><button className={display === "Table" ? styles.active : ""} onClick={() => setDisplay("Table")}>Table</button><button className={display === "Board" ? styles.active : ""} onClick={() => setDisplay("Board")}>Board</button></div></div>
      <div className={styles.toolbar}><label>View<select value={view} onChange={(e) => setView(e.target.value as View)}>{views.map((item) => <option key={item}>{item}</option>)}</select></label><label>Search<input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Customer, work, site, service" /></label><label>Owner<select value={ownerFilter} onChange={(e) => setOwnerFilter(e.target.value)}><option value="">All owners</option>{[...new Set(opportunities.map((item) => item.owner))].map((item) => <option key={item}>{item}</option>)}</select></label><label>Service<select value={serviceFilter} onChange={(e) => setServiceFilter(e.target.value)}><option value="">All services</option>{[...new Set(opportunities.map((item) => item.type))].map((item) => <option key={item}>{item}</option>)}</select></label><label>Customer<select value={customerFilter} onChange={(e) => setCustomerFilter(e.target.value)}><option value="">All customers</option>{[...new Set(opportunities.map((item) => item.customer))].map((item) => <option key={item}>{item}</option>)}</select></label><label>Customer buying<select value={commercialFilter} onChange={(e) => setCommercialFilter(e.target.value)}><option value="">Any commercial position</option>{["Unknown", "Early interest", "Budgeting", "Procurement", "Offer requested", "Offer submitted", "Negotiating", "Awarded", "Lost"].map((status) => <option key={status}>{status}</option>)}</select></label><label>Risk<select value={riskFilter} onChange={(e) => setRiskFilter(e.target.value)}><option value="">Any coverage</option><option value="Restricted">Restricted</option><option value="Incomplete">Incomplete assessment</option></select></label><label>Sort<select value={sort} onChange={(e) => setSort(e.target.value as typeof sort)}><option>Next action</option><option>Award date</option><option>Value</option></select></label><label>Saved view<select defaultValue="" onFocus={loadSavedViews} onChange={(event) => applySavedView(event.target.value)}><option value="">Choose a saved view</option>{savedViews.map((item) => <option key={item.name} value={item.name}>{item.name}</option>)}</select></label>{savingView ? <form onSubmit={(event) => { event.preventDefault(); saveCurrentView(); }}><label>Name view<input value={viewName} maxLength={50} onChange={(event) => setViewName(event.target.value)} required /></label><button className="d5o-primary">Save</button><button type="button" className="d5o-outline" onClick={() => setSavingView(false)}>Cancel</button></form> : <button className="d5o-outline" onClick={() => setSavingView(true)}>Save view</button>}</div>
      {display === "Table" ? <div className={styles.tableWrap}><table className={styles.table}><thead><tr><th>Opportunity / customer</th><th>Position</th><th>Recommendation</th><th>Indicative value</th><th>Next action</th></tr></thead><tbody>{visible.map((item) => { const c = item.discovery?.crm; const a = c?.assessmentHistory.at(-1); return <tr key={item.id} tabIndex={0} className={selected?.id === item.id ? styles.selected : ""} onClick={() => { onSelect(item.id); setTab("Overview"); }} onKeyDown={(event) => { if (event.key === "Enter" || event.key === " ") { event.preventDefault(); onSelect(item.id); setTab("Overview"); } }}><td><strong>{item.title}</strong><span>{item.customer} · {item.site} · {item.type}</span></td><td>{item.discovery?.pursuitControl?.status ?? "Legacy"}<span>Customer buying: {c?.commercialStatus ?? "Unknown"} · Legacy step: {item.discovery?.phase}</span></td><td>{a?.recommendation ?? "Not assessed"}<span>{a ? a.basis === assessmentBasis(item) ? `${a.coverage}% assessed` : "Reassessment required" : "Assessment needed"}</span></td><td>{c?.forecast.value === null || c?.forecast.value === undefined ? "Unknown" : money(c.forecast.value, c.forecast.currency)}<span>{c?.forecast.awardDate || "Award date unknown"} · {c?.forecast.probability === null || c?.forecast.probability === undefined ? "Probability unknown" : `${c.forecast.probability}% probability`} · {c?.forecast.category ?? "Unspecified"}</span></td><td>{item.nextAction}<span>{item.owner} · {item.nextActionDue || "No due date"} · {item.blockers.length} blockers · Last contact {c?.activities.at(-1)?.at.slice(0,10) ?? "unknown"}</span></td></tr>; })}</tbody></table></div> : <div className={styles.board}>{["draft", "submitted", "qualified", "held", "declined"].map((lane) => <div key={lane}><h3>{lane}</h3>{visible.filter((item) => (item.discovery?.pursuitControl?.status ?? "draft") === lane).map((item) => <button key={item.id} onClick={() => { onSelect(item.id); setTab("Overview"); }}><strong>{item.title}</strong><span>{item.customer}</span><small>{item.nextAction}</small></button>)}</div>)}</div>}{!visible.length ? <p className={styles.empty}>No opportunities match this view. Change filters or capture a new opportunity.</p> : null}
    </section>
    {selected ? <section className={`${styles.workspace} d5o-page-band`}><div className={styles.workspaceHeader}><div><p className={styles.eyebrow}>OPPORTUNITY WORKSPACE · {selected.id.toUpperCase()}</p><h2>{selected.title}</h2><p>{selected.customer} · {selected.site} · {selected.type}</p></div><button className="d5o-outline" onClick={() => onOpen(selected)}>Open Work Record →</button></div><div className={styles.context}><div><small>CUSTOMER / OWNER</small><strong>{selected.customer}</strong><span>{selected.owner}</span></div><div><small>CURRENT POSITION</small><strong>{selected.discovery?.pursuitControl?.status ?? "Legacy"}</strong><span>Customer buying: {crm.commercialStatus ?? "Unknown"}</span></div><div><small>VALUE / EXPECTED AWARD</small><strong>{crm.forecast.value === null ? "Unknown" : money(crm.forecast.value, crm.forecast.currency)}</strong><span>{crm.forecast.awardDate || "Award date unknown"}</span></div><div><small>NEXT ACTION</small><strong>{selected.nextAction}</strong><span>{selected.nextActionDue || "No due date"}</span></div></div><nav className={styles.tabs} aria-label="Discover workspace areas">{tabs.map((item) => <button key={item} className={tab === item ? styles.active : ""} onClick={() => setTab(item)}>{item}</button>)}</nav>
      <div className={styles.content}>{!crmEditable ? <p className={styles.warning}>This Work Record has moved beyond Discover. Its customer and commercial context is shown here for reference; open the current phase to make governed changes.</p> : null}{tab === "Overview" ? <><div className={styles.two}><article className={styles.card}><h3>Customer context</h3><p>{selected.customer} has {accountRecords.length} linked Discover opportunity{accountRecords.length === 1 ? "" : "s"} at {[...new Set(accountRecords.map((item) => item.site))].join(", ")}.</p><p>Identity: {crm.customerResolved ? "resolved" : "provisional"} customer · {crm.siteResolved ? "resolved" : "provisional"} site. {crm.externalCrmRef ? `External CRM reference: ${crm.externalCrmRef}` : "No external CRM reference."}</p><button className="d5o-outline" onClick={() => setCustomerOpen(true)}>View customer context →</button></article><article className={styles.card}><h3>What happens next</h3><p>{selected.nextAction}</p><p>Owner {selected.owner} · due {selected.nextActionDue || "not set"}. {crm.tasks.filter((task) => task.status === "Open").length} open follow-up task(s).</p><button className="d5o-outline" onClick={() => setTab("Activity & tasks")}>Open activities and tasks →</button></article></div><form className={styles.card} key={`${selected.id}-overview`} onSubmit={saveOverview}><h3>Opportunity working details</h3><div className={styles.formGrid}><label>Accountable owner<input name="owner" defaultValue={selected.owner} required /></label><label>Site / location<input name="site" defaultValue={selected.site} required /></label><label>Source<input name="source" defaultValue={selected.discovery?.source} /></label><label>Procurement route<input name="procurement" defaultValue={selected.discovery?.procurement} /></label><label>Funding<select name="funding" defaultValue={crm.funding}><option>Unknown</option><option>Unconfirmed</option><option>Confirmed</option></select></label><label>Customer commercial progress<select name="commercialStatus" defaultValue={crm.commercialStatus ?? "Unknown"}>{["Unknown", "Early interest", "Budgeting", "Procurement", "Offer requested", "Offer submitted", "Negotiating", "Awarded", "Lost"].map((status) => <option key={status}>{status}</option>)}</select></label><label>External CRM reference<input name="externalCrmRef" defaultValue={crm.externalCrmRef} placeholder="Optional reference, external source owns it" /></label><label>Governed next action<input name="nextAction" defaultValue={selected.nextAction} disabled={!!selected.canonicalWorkId} required /></label><label>Next action due<input type="date" name="nextDue" defaultValue={selected.nextActionDue ?? ""} /></label></div><label>Customer need<textarea name="need" defaultValue={selected.discovery?.need} rows={2} /></label><label>Desired customer outcome<textarea name="desiredOutcome" defaultValue={crm.desiredOutcome} rows={2} /></label><label>Business impact<textarea name="businessImpact" defaultValue={crm.businessImpact} rows={2} /></label><div className={styles.formGrid}><label>Urgency<select name="urgency" defaultValue={crm.urgency ?? "Unknown"}>{["Unknown", "Low", "Normal", "High", "Critical"].map((urgency) => <option key={urgency}>{urgency}</option>)}</select></label><label>Geography<input name="geography" defaultValue={crm.geography} /></label><label>Customer relationship<input name="customerRelationship" defaultValue={crm.customerRelationship} placeholder="Owner, prime, partner, channel or end customer" /></label></div><label>Preliminary scope<textarea name="preliminaryScope" defaultValue={crm.preliminaryScope} rows={2} /></label><label>Buying process<textarea name="buyingProcess" defaultValue={crm.buyingProcess} rows={2} /></label><label>Competition and alternatives<input name="competition" defaultValue={crm.competition} /></label><label>Partner / customer access<input name="access" defaultValue={crm.access} /></label><p className={styles.warning}>Customer and site names in this prototype are provisional. Linking a canonical account and site requires the authenticated Discover trial on a canonical Work Record.</p><button className="d5o-primary" disabled={!crmEditable}>Save working details</button></form><article className={styles.card}><h3>Opportunity timeline</h3><p>Customer interactions, assessments, controlled decisions and Work Record changes, newest first.</p><div className={styles.items}>{timeline.slice(0, 12).map((entry, index) => <div key={`${entry.at}-${index}`}><strong>{entry.at.slice(0, 10)} · {entry.title}</strong><span>{entry.actor}</span><small>{entry.detail}</small></div>)}</div>{!timeline.length ? <p>No activity or decision history yet.</p> : null}</article></> : null}
      {tab === "People & buying" ? <><article className={styles.card}><h3>Stakeholders and buying process</h3><p>One person may serve different roles on different opportunities. Their role here informs the pursuit assessment.</p><div className={styles.items}>{crm.contacts.map((person) => <div key={person.id}><strong>{person.name} · {person.role}</strong><span>{person.organization} · {person.influence} influence · {person.relationship}</span><small>{person.note}</small></div>)}</div><form className={styles.formGrid} onSubmit={addContact}><label>Name<input name="name" required /></label><label>Organization<input name="organization" required /></label><label>Opportunity role<select name="role">{["Sponsor", "Decision-maker", "Technical reviewer", "Procurement", "End user", "Champion", "Partner"].map((role) => <option key={role}>{role}</option>)}</select></label><label>Influence<select name="influence"><option>High</option><option>Medium</option><option>Low</option></select></label><label className={styles.wide}>Relationship note<input name="note" placeholder="Access, responsibility, open question" /></label><button className="d5o-primary" disabled={!crmEditable}>Add stakeholder</button></form>{reusableContacts.some((person) => !crm.contacts.some((linked) => linked.id === person.id)) ? <form className={styles.formGrid} onSubmit={linkContact}><h4 className={styles.wide}>Link an existing workspace contact</h4><label>Contact<select name="contactId">{reusableContacts.filter((person) => !crm.contacts.some((linked) => linked.id === person.id)).map((person) => <option key={person.id} value={person.id}>{person.name} · {person.organization}</option>)}</select></label><label>Role on this opportunity<select name="role">{["Sponsor", "Decision-maker", "Technical reviewer", "Procurement", "End user", "Champion", "Partner"].map((role) => <option key={role}>{role}</option>)}</select></label><label className={styles.wide}>Opportunity note<input name="note" /></label><button className="d5o-outline" disabled={!crmEditable}>Link contact</button></form> : null}</article><article className={styles.card}><h3>Buying gaps</h3><p>{crm.contacts.some((person) => person.role === "Decision-maker") ? "Decision-maker identified." : "Decision-maker not yet identified."} Funding is {crm.funding.toLowerCase()}. {crm.buyingProcess ? "Buying process recorded." : "Buying process unknown."}</p></article></> : null}
      {tab === "Activity & tasks" ? <div className={styles.two}><article className={styles.card}><h3>Customer activity</h3><form onSubmit={addActivity}><label>Type<select name="kind">{["Meeting", "Call", "Correspondence", "Site visit", "Document review", "Finding"].map((kind) => <option key={kind}>{kind}</option>)}</select></label><label>Summary<textarea name="summary" required rows={3} /></label><label>Related contacts<select name="contacts" multiple size={Math.min(4, Math.max(2, crm.contacts.length))}>{crm.contacts.map((person) => <option key={person.id} value={person.id}>{person.name}</option>)}</select></label><div className={styles.formGrid}><label>Resulting action<input name="resultingAction" placeholder="Optional follow-up task" /></label><label>Action owner<input name="actionOwner" defaultValue={actor} /></label><label>Action due<input name="actionDue" type="date" /></label></div><button className="d5o-primary" disabled={!crmEditable}>Record activity</button></form><div className={styles.items}>{crm.activities.slice().reverse().map((activity) => <div key={activity.id}><strong>{activity.kind} · {activity.at.slice(0, 10)}</strong><span>{activity.author} · {activity.contacts.map((id) => crm.contacts.find((person) => person.id === id)?.name).filter(Boolean).join(", ") || "No contacts linked"}</span><small>{activity.summary}{activity.resultingAction ? ` · Follow-up: ${activity.resultingAction}` : ""}</small></div>)}</div></article><article className={styles.card}><h3>Follow-up commitments</h3><form onSubmit={addTask}><label>Action<input name="title" value={taskDraft} onChange={(event) => setTaskDraft(event.target.value)} required /></label><label>Owner<input name="owner" defaultValue={selected.owner} required /></label><label>Due<input type="date" name="due" required /></label><button className="d5o-primary" disabled={!crmEditable}>Add task</button></form><div className={styles.items}>{crm.tasks.map((task) => <div key={task.id}><strong>{task.title}</strong><span>{task.owner} · {task.due} · {task.status}</span>{task.status === "Open" ? <button className="d5o-outline" disabled={!crmEditable} onClick={() => update((c) => ({ ...c, tasks: c.tasks.map((entry) => entry.id === task.id ? { ...entry, status: "Done", completedAt: new Date().toISOString() } : entry) }), "Task completed")}>Mark done</button> : null}</div>)}</div></article></div> : null}
      {tab === "Qualification" ? <div className={styles.two}><article className={styles.card}><h3>Assess pursuit fit</h3><p>{policy.source === "published" ? "Published tenant policy" : "Synthetic demo policy — configure a published policy before treating this as tenant authority"} · {policy.version}. Score anchors: 0 weak / 5 strong. Risk score means manageability, not risk severity.</p><form key={`${selected.id}-assessment-${assessment?.revision ?? 0}`} onSubmit={saveAssessment}><div className={styles.formGrid}>{(["strategicFit", "needCredibility", "commercialAttractiveness", "deliveryFeasibility", "risk"] as const).map((key) => <label key={key}>{key.replace(/([A-Z])/g, " $1")} · {policy.weights[key]}%<select name={key} defaultValue={crm[key] ?? ""}><option value="">Unknown</option>{[0,1,2,3,4,5].map((score) => <option key={score} value={score}>{score} / 5</option>)}</select></label>)}</div><label>Non-waivable restriction<select name="disqualifier" defaultValue={crm.disqualifier}><option>None</option><option>Legal restriction</option><option>Unsafe delivery</option><option>Outside service scope</option></select></label><button className="d5o-primary" disabled={!crmEditable || !versionId}>Save assessment revision</button></form></article><article className={styles.card}><h3>{assessment?.recommendation ?? "Recommendation not assessed"}</h3><p>Assessment {assessment?.revision ?? "—"} · coverage {assessment?.coverage ?? 0}% · weighted fit {assessment?.score ?? "unknown"}/100. Evidence confidence: {assessment?.evidenceConfidence ?? "Not assessed"}. This is advice, not a qualification decision or sales probability.</p>{changesSinceAssessment ? <p className={styles.warning}>Inputs changed since the last assessment. Reassess before relying on this result.</p> : null}<ul>{(assessment?.reasons ?? []).concat(assessment?.concerns ?? []).map((reason, index) => <li key={index}>{reason}</li>)}</ul><h4>What would change this?</h4><ul>{assessment?.conditions.map((condition) => { const assigned = crm.tasks.find((task) => task.title === condition && task.status === "Open"); return <li key={condition}>{condition}{assigned ? ` · ${assigned.owner} · due ${assigned.due}` : <button className="d5o-outline" onClick={() => { setTaskDraft(condition); setTab("Activity & tasks"); }}>Assign follow-up →</button>}</li>; })}</ul><details><summary>Score contributions and policy</summary>{assessment?.contributions.map((row) => <p key={row.label}>{row.label}: {row.score}/5 × {row.weight}%</p>)}</details><div className={styles.segment}><button className="d5o-outline" onClick={() => setTab("Overview")}>Review customer facts</button><button className="d5o-outline" onClick={() => setTab("People & buying")}>Review stakeholders</button><button className="d5o-outline" onClick={() => setTab("Evidence")}>Review evidence</button></div><button className="d5o-outline" onClick={() => setTab("Decision & handoff")}>Review decision and handoff →</button></article></div> : null}
      {tab === "Evidence" ? <article className={styles.card}><h3>Evidence and source references</h3><p>References support this opportunity but do not make unverified evidence authoritative.</p>{selected.proof.length ? <ul>{selected.proof.map((proof, index) => <li key={index}>{proof}</li>)}</ul> : <p>No evidence references linked yet.</p>}<p>Use the Work Record evidence controls for custody and review. This Discover view does not bypass that contract.</p><button className="d5o-outline" onClick={() => onOpen(selected)}>Open Work Record evidence →</button></article> : null}
      {tab === "Forecast" ? <><article className={styles.card}><h3>Indicative order forecast</h3><p>Contract value × recorded probability. Unknown probability stays unknown. This is not revenue, cash, margin or estimate pricing.</p><form key={`${selected.id}-forecast-${crm.forecast.reviewedAt ?? "new"}`} onSubmit={saveForecast}><div className={styles.formGrid}><label>Indicative contract value<input name="value" type="number" min="0" step="0.01" defaultValue={crm.forecast.value ?? ""} /></label><label>Currency<input name="currency" pattern="[A-Za-z]{3}" maxLength={3} defaultValue={crm.forecast.currency} required /></label><label>Recorded probability %<input name="probability" type="number" min="0" max="100" defaultValue={crm.forecast.probability ?? ""} /></label><label>Expected award date<input name="awardDate" type="date" defaultValue={crm.forecast.awardDate} /></label><label>Forecast category<select name="category" defaultValue={crm.forecast.category}>{["Unspecified", "Pipeline", "Best case", "Commit", "Excluded"].map((category) => <option key={category}>{category}</option>)}</select></label><label>Value basis<input name="basis" defaultValue={crm.forecast.basis} placeholder="Customer budget, rough order, market reference" /></label></div><label>Category and probability rationale<textarea name="rationale" defaultValue={crm.forecast.rationale} rows={2} /></label><button className="d5o-primary" disabled={!crmEditable}>Save dated forecast snapshot</button></form><p>Current weighted potential: {weightedPotential(crm) === null ? "Unknown — value or probability missing" : money(weightedPotential(crm)!, crm.forecast.currency)}.</p><details><summary>{crm.forecastSnapshots?.length ?? 0} dated snapshots</summary>{crm.forecastSnapshots?.slice().reverse().map((snap, index) => <p key={index}>{snap.at.slice(0, 10)} · {snap.period || "period unknown"} · {snap.currency} {snap.weighted === null ? "weighted unknown" : money(snap.weighted, snap.currency)} · source revision {snap.workRevision}</p>)}</details><button className="d5o-outline" type="button" onClick={() => { setForecastFocus([selected.id]); setSurface("Forecast"); }}>View Discover order forecast →</button></article></> : null}
      {tab === "Decision & handoff" ? <PursuitControl work={selected} actor={actor} canEdit={crmEditable || (Boolean(selected.canonicalWorkId && onPursuitCommand) && ["admin", "project_manager", "business_development_lead", "billing_commercial_lead", "operations_leader"].includes(actorRole ?? ""))} connected={Boolean(selected.canonicalWorkId && onPursuitCommand)} onCommand={onPursuitCommand} onUpdate={onUpdate} onNotice={onNotice} onDefine={onDefine} /> : null}
      </div></section> : <section className={`${styles.empty} d5o-page-band`}>No Discover opportunities yet. Capture one to begin customer development.</section>}
    </> : <section className={`${styles.pipeline} d5o-page-band`} aria-label="Indicative order forecast">
      <div className={styles.pipelineHeader}><div><p className={styles.eyebrow}>DISCOVER · COMMERCIAL OUTLOOK</p><h2>Indicative order forecast</h2></div><button className="d5o-outline" type="button" onClick={() => setSurface("Pipeline")}>← Opportunity pipeline</button></div>
      <p className={styles.forecastExplanation}>Expected customer awards from open opportunities. This is an order outlook, not revenue, billing, or cash. Each total opens its contributing opportunities; currencies remain separate.</p>
      <div className={styles.forecastControls}><label>Reporting period<select value={forecastPeriod} onChange={(event) => { setForecastPeriod(event.target.value as ForecastPeriod); setForecastFocus([]); }}><option value="month">Monthly</option><option value="quarter">Quarterly</option></select></label><span>{forecastRows.length} open {forecastRows.length === 1 ? "opportunity" : "opportunities"}; incomplete inputs are shown below</span></div>
      <div className={styles.forecastGrid}>{forecastGroups.map((group) => <button className={`${styles.forecastLine} ${forecastFocus.length && forecastFocus.every((id) => group.workIds.includes(id)) && forecastFocus.length === group.workIds.length ? styles.forecastSelected : ""}`} type="button" key={`${group.period}-${group.currency}-${group.category}`} onClick={() => setForecastFocus(group.workIds)}><strong>{group.period} · {group.currency} · {group.category}</strong><span>{money(group.unweighted, group.currency)} unweighted · {money(group.weighted, group.currency)} weighted</span><small>{group.workIds.length} contributing {group.workIds.length === 1 ? "opportunity" : "opportunities"} · {group.missingValue} missing value · {group.missingProbability} lacking weighted inputs · {group.pastDue} past-due award{group.pastDue === 1 ? "" : "s"}</small><small>Movement since prior snapshots: {group.movement === null ? "not yet comparable" : money(group.movement, group.currency)}</small></button>)}</div>
      {!forecastGroups.length ? <p className={styles.forecastExplanation}>No open opportunities have an indicative forecast yet. Record value, award date and probability on an opportunity to build this outlook.</p> : null}
      {forecastFocus.length ? <div className={styles.forecastContributors}><h3>Contributing opportunities</h3><p>Open a record to review or correct its forecast basis.</p>{opportunities.filter((item) => forecastFocus.includes(item.id)).map((item) => { const forecast = item.discovery?.crm?.forecast; return <button className={styles.forecastLine} type="button" key={item.id} onClick={() => { onSelect(item.id); setTab("Forecast"); setSurface("Pipeline"); }}><strong>{item.title} · {item.customer}</strong><span>{forecast?.value === null || forecast?.value === undefined ? "Value unknown" : money(forecast.value, forecast.currency)} · {forecast?.awardDate || "Award date unknown"} · {forecast?.probability === null || forecast?.probability === undefined ? "Probability unknown" : `${forecast.probability}% probability`}</span></button>; })}<button className="d5o-outline" type="button" onClick={() => setForecastFocus([])}>Clear selection</button></div> : <p className={styles.forecastExplanation}>Select a period and category above to inspect the opportunities behind its total.</p>}
      <p className={styles.forecastExplanation}>Held, declined, lost, no-bid, excluded and booked records are omitted. Missing inputs remain visible and are never treated as a known zero probability.</p>
    </section>}
    {captureOpen ? <div className={styles.scrim} onMouseDown={(event) => { if (event.target === event.currentTarget) setCaptureOpen(false); }}><aside className={styles.drawer} role="dialog" aria-modal="true" aria-label="Capture opportunity"><header><h2>Capture opportunity</h2><button onClick={() => setCaptureOpen(false)} aria-label="Close">×</button></header><p>Start a draft Work Record. Qualification details can be added later.</p><form onSubmit={capture}><label>Opportunity title<input name="title" required /></label><label>Customer / account<input name="customer" required list="discover-customers" /><datalist id="discover-customers">{[...new Set(opportunities.map((item) => item.customer))].map((customer) => <option key={customer} value={customer} />)}</datalist></label><label>Site / location<input name="site" list="discover-sites" /><datalist id="discover-sites">{[...new Set(opportunities.map((item) => item.site))].map((site) => <option key={site} value={site} />)}</datalist></label><label>Work Type<select name="type">{configuredTypes.map((type) => <option key={type}>{type}</option>)}</select></label><label>Source<select name="source"><option>Direct customer</option><option>Existing customer</option><option>Partner referral</option><option>Formal tender</option><option>Service renewal</option></select></label><label>Accountable owner<input name="owner" defaultValue={actor} /></label><label>Customer need<textarea name="need" rows={3} /></label><button className="d5o-primary" disabled={saving || !canEdit}>{saving ? "Checking configuration…" : "Capture draft opportunity"}</button></form></aside></div> : null}
    {customerOpen && selected ? <div className={styles.scrim} onMouseDown={(event) => { if (event.target === event.currentTarget) setCustomerOpen(false); }}><aside className={styles.drawer} role="dialog" aria-modal="true" aria-label="Customer context"><header><h2>{selected.customer}</h2><button onClick={() => setCustomerOpen(false)} aria-label="Close">×</button></header><p>Discover-only customer context from this workspace. Provisional names are grouped for review, not canonicalized automatically.</p><h3>Sites and opportunities</h3>{accountRecords.map((item) => <button key={item.id} className={styles.customerLink} onClick={() => { onSelect(item.id); setCustomerOpen(false); }}>{item.title}<span>{item.site} · {item.discovery?.pursuitControl?.status ?? "Legacy"}</span></button>)}<h3>Known contacts</h3>{accountContacts.map((person) => <p key={person.id}>{person.name} · {person.organization} · {person.role}</p>)}<h3>Recent activity and follow-up</h3>{accountRecords.flatMap((item) => item.discovery?.crm?.activities ?? []).sort((a,b) => b.at.localeCompare(a.at)).slice(0,5).map((activity) => <p key={activity.id}>{activity.at.slice(0,10)} · {activity.kind} · {activity.summary}</p>)}{accountRecords.flatMap((item) => item.discovery?.crm?.tasks ?? []).filter((task) => task.status === "Open").map((task) => <p key={task.id}>{task.due} · {task.title} · {task.owner}</p>)}</aside></div> : null}
  </main>;
}
